    for(int i=0; i&lt;n; i++)
        numeri[i] = rand() % 201 - 100;

    printf("\nMenu\n");
    printf("1) Stampa\n");
    printf("2) Minimo\n");
    printf("3) Massimo\n");
    printf("4) Media\n");
    printf("5) Moda\n");
    printf("6) Mediana\n");
    printf("7) Varianza\n");
    printf("8) Termina\n");

    int scelta;
    do{
        printf("Operazione da effettuare? ");
        scanf("%d", &amp;scelta);
        printf("\n");

        int val;
        switch(scelta){
            case 1:
                stampa(numeri, n);
                break;
            case 2:
                printf("Il minimo valore è: %d", minimo(numeri, n));
                break;
            case 3:
                printf("Il massimo valore è: %d", massimo(numeri, n));
                break;
            case 4:
                printf("La media vale: %.3f", media(numeri, n));
                break;
            case 5:
                val = moda(numeri, n);
                if(val==-1)
                    printf("Nessun valore modale");
                else
                    printf("Il valore modale è: %d", numeri[val]);
                break;
            case 6:
                printf("La mediana è: %d", mediana(numeri, n));
                break;
            case 7:
                printf("La varianza è: %.3f", varianza(numeri, n));
                break;
            case 8:
                break;
            default:
                printf("ERRORE: Scelta non disponibile.");
        };
        printf("\n");

    } while(scelta != 8);

    return 0;
}
</code></pre>

