&lt;body&gt;
  &lt;h1&gt;Calcolatrice&lt;/h1&gt;

  &lt;label for="num1"&gt;Primo numero&lt;/label&gt;
  &lt;input type="number" id="num1" value="20"&gt;

  &lt;label for="num2"&gt;Secondo numero&lt;/label&gt;
  &lt;input type="number" id="num2" value="4"&gt;

  &lt;div class="operazioni"&gt;
    &lt;button onclick="calcola('+')"&gt;+&lt;/button&gt;
    &lt;button onclick="calcola('-')"&gt;−&lt;/button&gt;
    &lt;button onclick="calcola('*')"&gt;×&lt;/button&gt;
    &lt;button onclick="calcola('/')"&gt;÷&lt;/button&gt;
  &lt;/div&gt;

  &lt;p id="risultato"&gt;&lt;/p&gt;

  &lt;script src="script.js"&gt;&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
