function cercaVittoria() {
  for (let k = 0; k &lt; combinazioni.length; k++) {
    const c = combinazioni[k];
    if (tavola[c[0]] !== "" &amp;&amp;
        tavola[c[0]] === tavola[c[1]] &amp;&amp;
        tavola[c[0]] === tavola[c[2]]) {
      return k;
    }
  }
  return -1;
}

