  if (vittoria !== -1) {
    stato.textContent = "Ha vinto " + turno + "!";
    finito = true;

    // Estensione: evidenzia le tre celle vincenti
    const c = combinazioni[vittoria];
    for (let k = 0; k &lt; 3; k++) {
      celle[c[k]].className = "cella vincente";
    }
