let punti = 0;
let tempo = 30;
let posizione = -1;      // buca in cui si trova la talpa (-1 = nessuna)
let giocando = false;
let idTempo;             // identificativo del timer del conto alla rovescia
let idTalpa;             // identificativo del timer che sposta la talpa

