    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Aeromobile)) return false;
        return sigla.equals(((Aeromobile) obj).sigla);
    }

    @Override
    public String toString() {
        return "[" + getClass().getSimpleName() + " | sigla: " + sigla + "]";
    }
}
