}

function ePrimo(int $n): bool
{
    if ($n &lt; 2) {
        return false;
    }
    for ($d = 2; $d * $d &lt;= $n; $d++) {
        if ($n % $d === 0) {
            return false;
        }
    }
    return true;
}

function fattoriale(int $n): int
{
    return $n &lt;= 1 ? 1 : $n * fattoriale($n - 1);
}

function conIva(float $prezzo, float $aliquota = 22): float
{
