    if (!is_numeric($n1) || !is_numeric($n2)) {
        $errore = "Inserisci due numeri validi.";
    } else {
        $a = (float) $n1;
        $b = (float) $n2;
        if ($operazione === "/" &amp;&amp; $b == 0) {
            $errore = "Non si può dividere per zero.";
        } else {
            $risultato = match ($operazione) {
                "+" =&gt; $a + $b,
                "-" =&gt; $a - $b,
                "*" =&gt; $a * $b,
                "/" =&gt; $a / $b,
                "^" =&gt; $a ** $b,
                default =&gt; null,
            };
            if ($risultato === null) {
                $errore = "Operazione non riconosciuta.";
            }
        }
    }
}
