$righe = $pdo-&gt;query(
    "SELECT c.nome AS categoria, p.id, p.nome, p.descrizione, p.prezzo, p.giacenza
     FROM prodotti p
     JOIN categorie c ON c.id = p.id_categoria
     ORDER BY c.nome, p.nome"
)-&gt;fetchAll();

// Raggruppamento in PHP: categoria =&gt; elenco dei prodotti
$perCategoria = [];
