// Restituisce ["id" =&gt; ..., "username" =&gt; ...] dell'utente autenticato oppure null
function utente(): ?array
{
    return isset($_SESSION["utente_id"])
        ? ["id" =&gt; $_SESSION["utente_id"], "username" =&gt; $_SESSION["utente_username"]]
        : null;
}

function richiediUtente(): array
{
